-- Legacy production baseline. Keep aligned with the real Supabase schema.
create extension if not exists pgcrypto;
create table if not exists public.hosts(id uuid primary key default gen_random_uuid(),user_id uuid,business_name text,contact_name text,phone text,line_id text,email text,status text not null default 'active' check(status in('active','inactive','pending')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.listings(id uuid primary key default gen_random_uuid(),name text,location text,price numeric,slug text,description text,price_unit text default 'night',capacity integer default 1,category text default 'stay',vibe text[] default '{}',amenities text[] default '{}',pet_friendly boolean default false,party_friendly boolean default false,status text default 'published',created_at timestamptz default now(),updated_at timestamptz default now(),host_id uuid references public.hosts(id),address text,latitude double precision check(latitude is null or latitude between -90 and 90),longitude double precision check(longitude is null or longitude between -180 and 180),google_maps_url text,images text[]);
create table if not exists public.listing_images(id uuid primary key default gen_random_uuid(),listing_id uuid not null references public.listings(id),image_url text not null,sort_order integer not null default 0,created_at timestamptz not null default now());
create table if not exists public.leads(id uuid primary key default gen_random_uuid(),listing_id uuid references public.listings(id),user_id uuid,action text not null,source text,contact_name text,contact_phone text,contact_line text,created_at timestamptz not null default now());
create table if not exists public.trip_sessions(id uuid primary key default gen_random_uuid(),user_id uuid,destination text,start_date date,end_date date,travelers integer,budget numeric,preferences jsonb not null default '{}',result jsonb,created_at timestamptz not null default now());
